import math

def sum_of_divisors(m):
    """Calculates sigma_1(m), the sum of all divisors of m."""
    total = 0
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            total += i
            if i * i != m:
                total += m // i
    return total

def is_perfect_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

print("Candidates m (2 <= m <= 20) where sigma_1(m) is a perfect square:")
candidates = []
for m in range(2, 21):
    sigma = sum_of_divisors(m)
    if is_perfect_square(sigma):
        candidates.append(m)
        print(f"m = {m}: sigma_1(m) = {sigma} (Square: {is_perfect_square(sigma)})")

print("\nList of candidates:", candidates)

