import itertools
import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_permutation(p):
    partial_sums = []
    current_sum = 0
    for a in p:
        current_sum += a
        partial_sums.append(current_sum)

    # Check if all partial sums are perfect squares
    for s in partial_sums:
        if not is_perfect_square(s):
            return False
    return True

